<script setup>
import {ref} from 'vue';import {audioTranscript} from '../data/chapters';const props=defineProps({src:String,transcript:{type:String,default:audioTranscript}});const audio=ref(null),playing=ref(false),time=ref(0),duration=ref(0),error=ref(false);const format=n=>Number.isFinite(n)?`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`:'0:00';async function toggle(){if(!audio.value)return;if(playing.value){audio.value.pause()}else{try{await audio.value.play()}catch{error.value=true}}}function seek(e){audio.value.currentTime=Number(e.target.value)}
</script><template><section class="audio-block" aria-label="Аудиокомментарий"><p class="eyebrow">ПОСЛУШАТЬ ГЛАВНОЕ</p><h3>Инфраструктура доверия</h3><p class="audio-credit">Авторский текст, синтезированная озвучка · русский язык</p><audio ref="audio" :src="src" preload="none" @loadedmetadata="duration=audio.duration" @timeupdate="time=audio.currentTime" @play="playing=true" @pause="playing=false" @ended="playing=false" @error="error=true"></audio><div class="audio-controls"><button @click="toggle" :aria-label="playing?'Приостановить аудио':'Воспроизвести аудио'">{{playing?'Ⅱ':'▶'}}</button><label class="audio-seek"><span class="sr-only">Позиция воспроизведения</span><input type="range" min="0" :max="duration||1" step="0.1" :value="time" @input="seek"></label><span>{{format(time)}} / {{format(duration)}}</span></div><p v-if="error" role="status">Воспроизведение недоступно в этой среде. Ниже доступна полная расшифровка.</p><details><summary>Текст аудиокомментария</summary><p>{{transcript}}</p></details></section></template>
